Definition tab_ok (ws : list word) (i : Z) : Prop :=
  forall j w, 0 <= j < i -> nth_error ws (Z.to_nat j) = Some w -> exists s, w = Z_to_bv 64 s /\ 0 <= s <= 8.

Lemma tab_ok_0 : forall ws, tab_ok ws 0.
Proof.
